66	function formatDateTime(iso: string) {
67	  const d = new Date(iso);
68	  return d.toLocaleString("lt-LT", { weekday: "long", year: "numeric", month: "long", day: "numeric", hour: "2-digit", minute: "2-digit" });
69	}
