71	function EloBadge({ elo, sport }: { elo: number; sport?: string }) {
72	  const t = getTier(elo);
73	  const sportEmoji = sport ? getSportEmoji(sport) : null;
74	  return (
75	    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold border ${t.bgCls} ${t.cls}`}>
