81	interface UserSearchResult { userId: string; userName: string; }
82	
83	function PlayerSearchAdd({ gameId, sport, onAdded }: { gameId: number; sport: string; onAdded: () => void }) {
84	  const { toast } = useToast();
85	  const [query, setQuery] = useState("");
86	  const [open, setOpen] = useState(false);
87	
88	  const { data: results, isLoading } = useQuery<UserSearchResult[]>({
89	    queryKey: ["user-search", query],
90	    queryFn: () => customFetch<UserSearchResult[]>(`${API}/users/search?q=${encodeURIComponent(query)}`),
91	    enabled: query.length >= 2,
92	  });
93	
94	  const addPlayer = useMutation({
95	    mutationFn: (u: UserSearchResult) => customFetch(`${API}/games/${gameId}/add-player`, {
96	      method: "POST",
97	      headers: { "Content-Type": "application/json" },
98	      body: JSON.stringify({ targetUserId: u.userId, targetUserName: u.userName }),
99	    }),
100	    onSuccess: () => {
101	      toast({ title: "Žaidėjas pridėtas!" });
102	      setOpen(false);
103	      setQuery("");
104	      onAdded();
105	    },
106	    onError: (e: any) => toast({ title: "Klaida", description: e?.message, variant: "destructive" }),
107	  });
108	
109	  return (
110	    <Dialog open={open} onOpenChange={setOpen}>
111	      <DialogTrigger asChild>
112	        <Button variant="outline" size="sm" className="gap-1.5">
113	          <Search className="w-3.5 h-3.5" />
114	          Ieškoti žaidėjo
115	        </Button>
116	      </DialogTrigger>
117	      <DialogContent className="sm:max-w-sm">
118	        <DialogHeader>
119	          <DialogTitle>Pridėti žaidėją</DialogTitle>
120	          <DialogDescription>Suraskite žaidėją pagal vardą</DialogDescription>
121	        </DialogHeader>
122	        <div className="space-y-3 py-1">
123	          <div className="relative">
124	            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
125	            <Input
126	              placeholder="Vardas..."
127	              className="pl-9"
128	              value={query}
129	              onChange={e => setQuery(e.target.value)}
130	              autoFocus
131	            />
132	          </div>
133	          {query.length >= 2 && (
134	            <div className="space-y-1 max-h-56 overflow-y-auto">
135	              {isLoading && <p className="text-xs text-center text-muted-foreground py-4">Ieškoma...</p>}
136	              {!isLoading && (!results || results.length === 0) && (
137	                <p className="text-xs text-center text-muted-foreground py-4">Nieko nerasta</p>
138	              )}
139	              {results?.map(u => (
140	                <button
141	                  key={u.userId}
142	                  onClick={() => addPlayer.mutate(u)}
143	                  disabled={addPlayer.isPending}
144	                  className="w-full flex items-center gap-3 p-2.5 rounded-lg hover:bg-muted/50 transition-colors text-left"
145	                >
146	                  <div className="w-8 h-8 rounded-full bg-primary/15 flex items-center justify-center text-xs font-bold text-primary">
147	                    {u.userName.split(" ").map(n => n[0]).join("").slice(0, 2).toUpperCase()}
148	                  </div>
149	                  <div className="flex-1 min-w-0">
150	                    <div className="text-sm font-medium truncate">{u.userName}</div>
151	                  </div>
152	                  <UserPlus className="w-4 h-4 text-muted-foreground shrink-0" />
153	                </button>
154	              ))}
155	            </div>
156	          )}
157	        </div>
158	      </DialogContent>
159	    </Dialog>
160	  );
161	}
