268	function VerifyResultSection({ gameId, result, isParticipant }: {
269	  gameId: number; result: GameResult; isParticipant: boolean;
270	}) {
271	  const { toast } = useToast();
272	  const qc = useQueryClient();
273	
274	  const verify = useMutation({
275	    mutationFn: (action: "confirm" | "dispute") => customFetch(`${API}/games/${gameId}/verify`, {
276	      method: "POST", headers: { "Content-Type": "application/json" },
277	      body: JSON.stringify({ action }),
278	    }),
279	    onSuccess: (_, action) => {
280	      qc.invalidateQueries({ queryKey: ["game", gameId] });
281	      qc.invalidateQueries({ queryKey: ["game-result", gameId] });
282	      toast({
283	        title: action === "confirm" ? "Rezultatas patvirtintas!" : "Rezultatas ginčijamas",
284	        description: action === "confirm" ? "ELO reitingai atnaujinti." : "Organizatorius gavo pranešimą.",
285	      });
286	    },
287	    onError: (e: any) => toast({ title: "Klaida", description: e?.message, variant: "destructive" }),
288	  });
289	
290	  if (!isParticipant || result.status !== "pending_verification") return null;
291	
292	  return (
293	    <div className="flex flex-wrap gap-2 mt-3">
294	      <Button
295	        size="sm"
296	        className="bg-green-600 hover:bg-green-700 text-white gap-1.5"
297	        onClick={() => verify.mutate("confirm")}
298	        disabled={verify.isPending}
299	      >
300	        <CheckCircle2 className="w-4 h-4" />Patvirtinti rezultatą
301	      </Button>
302	      <Button
303	        size="sm"
304	        variant="outline"
305	        className="border-red-500/40 text-red-500 hover:bg-red-500/10 gap-1.5"
306	        onClick={() => verify.mutate("dispute")}
307	        disabled={verify.isPending}
308	      >
309	        <XCircle className="w-4 h-4" />Ginčyti
310	      </Button>
311	    </div>
312	  );
313	}
