371	interface GameRefundPreview {
372	  gameId: number;
373	  bookingId: number | null;
374	  hasBooking: boolean;
375	  totalPrice: number;
376	  hoursBeforeStart: number;
377	  refundPercent: number;
378	  refundAmount: number;
379	  refundable: boolean;
380	  canCancel: boolean;
381	  reason?: string;
382	}
383	
384	function CancelGameDialog({
385	  gameId,
386	  hasBooking,
387	  onConfirmed,
388	  pending,
389	}: {
390	  gameId: number;
391	  hasBooking: boolean;
392	  onConfirmed: () => Promise<unknown>;
393	  pending: boolean;
394	}) {
395	  const [open, setOpen] = useState(false);
396	  const [submitting, setSubmitting] = useState(false);
397	
398	  const { data: preview, isLoading } = useQuery<GameRefundPreview>({
399	    queryKey: ["game-refund-preview", gameId],
400	    queryFn: () => customFetch<GameRefundPreview>(`${API}/games/${gameId}/refund-preview`),
401	    enabled: open && hasBooking,
402	    staleTime: 0,
403	  });
404	
405	  // If preview has loaded, trust its hasBooking (handles the orphan case where
406	  // game.bookingId points at a missing/deleted booking row → fall back to plain warning).
407	  const effectiveHasBooking = preview ? preview.hasBooking : hasBooking;
408	  const showRefundUi = effectiveHasBooking && (isLoading || !!preview);
409	  const refundEur = preview?.refundAmount ?? 0;
410	  const totalPaid = preview?.totalPrice ?? 0;
411	  const isLate = preview ? !preview.refundable : false;
412	  const tierMsg = !preview
413	    ? ""
414	    : (preview.refundPercent >= 80
415	        ? "Atšaukus dabar, bus grąžinta 80% sumos."
416	        : preview.refundPercent >= 50
417	          ? "Atšaukus dabar, bus grąžinta 50% sumos."
418	          : "Atšaukus dabar, pinigai nebus grąžinami.");
419	
420	  const blockedByPolicy = effectiveHasBooking && preview && !preview.canCancel;
421	
422	  const handleConfirm = async () => {
423	    setSubmitting(true);
424	    try {
425	      await onConfirmed();
426	      setOpen(false);
427	    } finally {
428	      setSubmitting(false);
429	    }
430	  };
431	
432	  return (
433	    <Dialog open={open} onOpenChange={(v) => !submitting && !pending && setOpen(v)}>
434	      <DialogTrigger asChild>
435	        <Button variant="destructive" size="sm">
436	          <Trash2 className="w-4 h-4 mr-1.5" />Panaikinti žaidimą
437	        </Button>
438	      </DialogTrigger>
439	      <DialogContent className="max-w-md">
440	        <DialogHeader>
441	          <DialogTitle>Panaikinti žaidimą?</DialogTitle>
442	          <DialogDescription>
443	            {!hasBooking
444	              ? "Visi dalyviai bus pašalinti. Šio veiksmo atšaukti negalima."
445	              : isLoading || !preview
446	                ? "Skaičiuojamas grąžintinas mokestis…"
447	                : blockedByPolicy
448	                  ? (preview.reason ?? "Atšaukti šiuo metu negalima.")
449	                  : tierMsg}
450	          </DialogDescription>
451	        </DialogHeader>
452	
453	        {showRefundUi && preview && preview.canCancel && totalPaid > 0 && (
454	          <div className="rounded-lg border bg-muted/40 p-3 text-sm space-y-1.5">
455	            <div className="flex justify-between">
456	              <span className="text-muted-foreground">Sumokėta</span>
457	              <span className="font-medium">€{totalPaid.toFixed(2)}</span>
458	            </div>
459	            <div className="flex justify-between">
460	              <span className="text-muted-foreground">Grąžinama</span>
461	              <span className="font-medium">{preview.refundPercent}%</span>
462	            </div>
463	            <div className="flex justify-between border-t pt-1.5 mt-1.5">
464	              <span className="font-semibold">Grąžinama suma</span>
465	              <span className={`font-bold ${isLate ? "text-destructive" : "text-green-600 dark:text-green-400"}`}>
466	                €{refundEur.toFixed(2)}
467	              </span>
468	            </div>
469	          </div>
470	        )}
471	
472	        <p className="text-xs text-muted-foreground">
473	          {hasBooking
474	            ? "Grąžinimo politika: ≥48h iki pradžios — 80%, ≥24h — 50%, mažiau — 0%."
475	            : "Visi prisijungę dalyviai bus informuoti."}
476	        </p>
477	
478	        <DialogFooter className="gap-2">
479	          <Button variant="outline" onClick={() => setOpen(false)} disabled={submitting || pending}>
480	            Atšaukti
481	          </Button>
482	          <Button
483	            variant="destructive"
484	            onClick={handleConfirm}
485	            disabled={submitting || pending || (hasBooking && !!blockedByPolicy)}
486	          >
487	            {(submitting || pending) ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : null}
488	            Panaikinti žaidimą
489	          </Button>
490	        </DialogFooter>
491	      </DialogContent>
492	    </Dialog>
493	  );
494	}
