33	router.post("/payments/create-checkout", async (req, res): Promise<void> => {
34	  const parsed = CreateCheckoutSessionBody.safeParse(req.body);
35	  if (!parsed.success) {
36	    res.status(400).json({ error: parsed.error.message });
37	    return;
38	  }
39	
40	  const { bookingId, successUrl, cancelUrl } = parsed.data;
41	  // Guest checkout passes the management token in the body (CreateCheckoutSessionBody
42	  // doesn't list it, so read it raw — we never trust it without comparing to DB).
43	  const providedToken =
44	    typeof (req.body as any)?.managementToken === "string"
45	      ? ((req.body as any).managementToken as string)
46	      : null;
47	
48	  const rows = await db
49	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
50	    .from(bookingsTable)
51	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
52	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
53	    .where(eq(bookingsTable.id, bookingId));
