34	function toMin(t: string): number {
35	  const [h, m] = t.split(":").map(Number);
36	  return h * 60 + m;
37	}
38	
39	function slotsBetween(startTime: string, endTime: string): string[] {
40	  const slots: string[] = [];
41	  let cur = toMin(startTime);
42	  const end = toMin(endTime);
43	  while (cur < end) {
44	    const h = Math.floor(cur / 60).toString().padStart(2, "0");
45	    const m = (cur % 60).toString().padStart(2, "0");
46	    slots.push(`${h}:${m}`);
47	    cur += 30;
48	  }
49	  return slots;
50	}
