75	router.post("/games/checkout-split", requireAuth, async (req, res): Promise<void> => {
76	  const userId = getCurrentUserId(req)!;
77	  const parsed = SplitCheckoutBody.safeParse(req.body);
78	  if (!parsed.success) {
79	    res.status(400).json({ error: parsed.error.message });
80	    return;
81	  }
82	
83	  const {
84	    courtId, date, startTime, endTime, totalSlots, sport, skillLevel, description,
85	    customerName, customerEmail, customerPhone,
86	    isPublic, minSkillLevel, maxSkillLevel, matchType,
87	    linkGameId,
88	  } = parsed.data;
89	
90	  const reqStartMin = toMin(startTime);
91	  const reqEndMin = toMin(endTime);
92	  if (reqEndMin <= reqStartMin) {
93	    res.status(400).json({ error: "endTime must be after startTime" });
94	    return;
95	  }
96	
97	  // ── Fetch court and facility ──────────────────────────────────────────────
98	  const [courtRow] = await db
99	    .select({ court: courtsTable, facility: facilitiesTable })
100	    .from(courtsTable)
101	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
102	    .where(eq(courtsTable.id, courtId));
103	
104	  if (!courtRow?.court) {
105	    res.status(404).json({ error: "Court not found" });
106	    return;
107	  }
108	
109	  const { court, facility } = courtRow;
110	
111	  // ── Server-side price calculation ─────────────────────────────────────────
112	  const dateObj = new Date(`${date}T12:00:00`);
113	  const dayOfWeek = dateObj.getDay();
114	
115	  const pricingEntries = await db.select()
116	    .from(courtPricingTable)
117	    .where(and(
118	      eq(courtPricingTable.courtId, courtId),
119	      eq(courtPricingTable.dayOfWeek, dayOfWeek),
120	    ));
121	
122	  const pricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
123	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
124	
125	  const slots = slotsBetween(startTime, endTime);
126	  let courtPrice = 0;
127	  for (const slotStart of slots) {
128	    courtPrice += pricingMap.has(slotStart) ? pricingMap.get(slotStart)! : defaultSlotPrice;
129	  }
130	
131	  const totalPrice = courtPrice;
132	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
133	  const durationMinutes = reqEndMin - reqStartMin;
134	
135	  // ── Conflict check ────────────────────────────────────────────────────────
136	  const conflictingBookings = await db
137	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
138	    .from(bookingsTable)
139	    .where(and(
140	      eq(bookingsTable.courtId, courtId),
141	      eq(bookingsTable.date, date),
142	      sql`${bookingsTable.status} IN ('confirmed', 'blocked', 'awaiting_players')`,
