149	      eq(bookingsTable.courtId, courtId),
150	      eq(bookingsTable.date, date),
151	      eq(bookingsTable.status, "pending"),
152	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
153	    ));
154	
155	  const allConflicting = [...conflictingBookings, ...recentPending];
156	  for (const b of allConflicting) {
157	    const bStart = toMin(b.startTime);
158	    const bEnd = toMin(b.endTime);
159	    if (reqStartMin < bEnd && reqEndMin > bStart) {
