170	      eq(courtBlockedSlotsTable.courtId, courtId),
171	      eq(courtBlockedSlotsTable.date, date),
172	    ));
173	
174	  for (const b of blockedSlots) {
175	    const bStart = toMin(b.startTime);
176	    const bEnd = toMin(b.endTime);
