392	router.post("/payments/confirm-split", async (req, res): Promise<void> => {
393	  const sessionId = String(req.body?.sessionId ?? "");
394	  if (!sessionId) { res.status(400).json({ error: "sessionId required" }); return; }
395	
396	  // Find the booking by stripeSessionId
397	  const [booking] = await db
398	    .select()
399	    .from(bookingsTable)
400	    .where(eq(bookingsTable.stripeSessionId, sessionId));
401	
402	  if (!booking) { res.status(404).json({ error: "Booking not found for session" }); return; }
403	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
404	
405	  // Verify Stripe payment and read metadata (skip for mocks)
406	  let linkGameId: number | null = null;
407	  if (!sessionId.startsWith("mock_")) {
408	    try {
409	      const stripe = await getUncachableStripeClient();
410	      const session = await stripe.checkout.sessions.retrieve(sessionId);
411	      if (session.payment_status !== "paid") {
412	        res.status(402).json({ error: "Payment not completed" });
413	        return;
414	      }
415	      const lgId = session.metadata?.linkGameId;
416	      if (lgId) linkGameId = parseInt(lgId, 10);
417	    } catch (err) {
418	      logger.error({ err }, "Stripe retrieve session error in confirm-split");
419	    }
420	  }
421	
422	  // Find participant by stripeSessionId → mark as paid (idempotent)
423	  const [participant] = await db
424	    .select()
425	    .from(gameParticipantsTable)
426	    .where(eq(gameParticipantsTable.stripeSessionId, sessionId));
427	
428	  if (participant && participant.paymentStatus !== "paid") {
429	    await db
430	      .update(gameParticipantsTable)
431	      .set({ paymentStatus: "paid" })
432	      .where(eq(gameParticipantsTable.id, participant.id));
433	  }
434	
435	  // Move booking to awaiting_players (from pending)
436	  if (booking.status === "pending") {
437	    await db
438	      .update(bookingsTable)
439	      .set({ status: "awaiting_players" })
440	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")));
441	  }
442	
443	  // Find linked game and transition it
444	  let game: typeof gamesTable.$inferSelect | undefined;
445	  if (linkGameId) {
446	    // Upgrade flow: update the pre-existing casual game
447	    const [courtRow] = await db
448	      .select({ facilityId: facilitiesTable.id, courtId: courtsTable.id })
449	      .from(courtsTable)
450	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
451	      .where(eq(courtsTable.id, booking.courtId));
452	    await db
453	      .update(gamesTable)
454	      .set({
455	        bookingId: booking.id,
456	        facilityId: courtRow?.facilityId ?? null,
457	        courtId: courtRow?.courtId ?? booking.courtId,
458	        status: "awaiting_players",
459	      })
460	      .where(eq(gamesTable.id, linkGameId));
461	    const [updated] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
462	    game = updated;
463	  } else {
464	    // Normal flow: find the game that was created alongside this booking
465	    const [found] = await db
466	      .select()
467	      .from(gamesTable)
468	      .where(eq(gamesTable.bookingId, booking.id));
469	    if (found && found.status === "pending_payment") {
470	      await db
471	        .update(gamesTable)
472	        .set({ status: "awaiting_players" })
473	        .where(and(eq(gamesTable.id, found.id), eq(gamesTable.status, "pending_payment")));
474	    }
475	    game = found;
476	  }
477	
478	  // Aggregate paid participant count
479	  const allParticipants = game
480	    ? await db
481	        .select({ paymentStatus: gameParticipantsTable.paymentStatus })
482	        .from(gameParticipantsTable)
483	        .where(and(
484	          eq(gameParticipantsTable.gameId, game.id),
485	          eq(gameParticipantsTable.status, "joined"),
486	        ))
487	    : [];
488	  const paidSlots = allParticipants.filter(p => p.paymentStatus === "paid").length;
489	
490	  res.json({
491	    bookingId: booking.id,
492	    gameId: game?.id ?? null,
493	    shareToken: booking.splitInviteToken ?? null,
494	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
495	    totalSlots: booking.totalSlots ?? 1,
496	    paidSlots,
497	    totalPrice: Number(booking.totalPrice),
498	    date: booking.date,
499	    startTime: booking.startTime,
500	    endTime: booking.endTime,
501	    sport: game?.sport ?? null,
502	    isPublic: game?.visibility === "public",
503	  });
504	});
