522	router.delete("/games/:id", requireAuth, async (req, res): Promise<void> => {
523	  const id = parseInt(String(req.params.id), 10);
524	  const userId = getCurrentUserId(req)!;
525	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
526	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
527	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
528	
529	  // ─── Single-owner cancellation claim ─────────────────────────────────────────
530	  // CAS the game into 'cancelling' so that concurrent DELETEs are rejected with 409.
531	  // Without this, a second request could race past the booking-CAS (which would
532	  // already be claimed) and delete the game while the first request's Stripe call
533	  // is still in flight, producing "game deleted but booking still confirmed and
534	  // no refund issued" if Stripe then fails and the first request rolls booking back.
535	  const originalStatus = g.status;
536	  const claimGame = await db
537	    .update(gamesTable)
538	    .set({ status: "cancelling" })
539	    .where(and(eq(gamesTable.id, id), ne(gamesTable.status, "cancelling")))
540	    .returning();
541	  if (claimGame.length === 0) {
542	    res.status(409).json({ error: "Atšaukimas jau vykdomas. Bandykite po akimirkos." });
543	    return;
544	  }
545	
546	  // ─── If a paid Korts.lt booking is linked, mirror the standard booking-cancel + refund flow ──
547	  let refundedAmount = 0;
548	  let refundPercent = 0;
549	  if (g.bookingId) {
550	    const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, g.bookingId));
551	    if (booking && booking.status !== "cancelled") {
552	      const totalPriceEur = Number(booking.totalPrice);
553	      const hours = hoursBeforeStart(booking.date, booking.startTime);
554	      if (hours <= 0) {
555	        res.status(400).json({ error: "Žaidimas jau prasidėjo arba pasibaigė", code: "CANCEL_TOO_LATE" });
556	        return;
557	      }
558	      const tier = computeRefund(totalPriceEur, hours);
559	
560	      // CAS on booking status to prevent double-refund if the host clicks twice or the
561	      // sweeper races us on a still-pending booking.
562	      const claimed = await db
563	        .update(bookingsTable)
564	        .set({ status: "cancelled" })
565	        .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
566	        .returning();
567	
568	      if (claimed.length > 0) {
569	        let stripeRefundId: string | null = null;
570	        if (
571	          tier.refundable &&
572	          tier.refundAmount > 0 &&
573	          booking.stripePaymentIntentId &&
574	          !booking.stripePaymentIntentId.startsWith("mock_")
575	        ) {
576	          try {
577	            const stripe = await getUncachableStripeClient();
578	            const refund = await stripe.refunds.create(
579	              {
580	                payment_intent: booking.stripePaymentIntentId,
581	                amount: Math.round(tier.refundAmount * 100),
582	                reason: "requested_by_customer",
583	              },
584	              { idempotencyKey: `cancel-game-${g.id}` },
585	            );
586	            stripeRefundId = refund.id;
587	            logger.info(
588	              { gameId: g.id, bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount },
589	              "Stripe refund issued for host-cancelled game",
590	            );
591	          } catch (err) {
592	            logger.error({ err, gameId: g.id, bookingId: booking.id }, "Stripe refund failed");
593	            // Roll back BOTH booking and game status so the host can retry.
594	            // Without restoring game.status, the next attempt would 409 forever.
595	            await db
596	              .update(bookingsTable)
597	              .set({ status: booking.status })
598	              .where(eq(bookingsTable.id, booking.id));
599	            await db
600	              .update(gamesTable)
601	              .set({ status: originalStatus })
602	              .where(eq(gamesTable.id, g.id));
603	            res.status(502).json({ error: "Nepavyko grąžinti pinigų. Bandykite dar kartą." });
604	            return;
605	          }
606	        }
607	
608	        await db
609	          .update(bookingsTable)
610	          .set({ refundAmount: String(tier.refundAmount), stripeRefundId })
611	          .where(eq(bookingsTable.id, booking.id));
612	
613	        refundedAmount = tier.refundAmount;
614	        refundPercent = tier.refundPercent;
615	      }
616	    }
617	  }
618	
