851	router.delete("/games/:id/leave", requireAuth, async (req, res): Promise<void> => {
852	  const id = parseInt(String(req.params.id), 10);
853	  const userId = getCurrentUserId(req)!;
854	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
855	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
856	  if (g.creatorUserId === userId) {
857	    res.status(400).json({ error: "Creator cannot leave — delete the game instead" }); return;
858	  }
859	
860	  // Single-transition CAS: only flip rows that are currently `joined`. If 0 rows
861	  // updated, the user wasn't actually joined → idempotent no-op (no penalty).
862	  const flipped = await db
863	    .update(gameParticipantsTable)
864	    .set({ status: "left" })
865	    .where(and(
866	      eq(gameParticipantsTable.gameId, id),
867	      eq(gameParticipantsTable.userId, userId),
868	      eq(gameParticipantsTable.status, "joined"),
869	    ))
870	    .returning({ id: gameParticipantsTable.id });
871	
872	  if (flipped.length === 0) {
873	    // Already left (or never joined) — return idempotently without penalty.
874	    res.json({ ok: true, alreadyLeft: true }); return;
875	  }
876	
877	  // Re-open if was full
878	  if (g.status === "full") {
879	    await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, id));
880	  }
881	
882	  // ─── Reliability penalty: leaving within 12h of game start costs 10 points ──
883	  const now = Date.now();
884	  const startMs = new Date(g.datetime).getTime();
885	  const hoursUntilStart = (startMs - now) / (1000 * 60 * 60);
886	  const wasActive = g.status === "open" || g.status === "full";
887	  if (wasActive && hoursUntilStart > 0 && hoursUntilStart < 12) {
888	    // Ensure a profile row exists, then decrement (clamp at 0).
889	    const [existing] = await db.select({ score: userProfilesTable.reliabilityScore })
890	      .from(userProfilesTable).where(eq(userProfilesTable.userId, userId));
891	    if (!existing) {
892	      await db.insert(userProfilesTable).values({ userId, reliabilityScore: 90 }).onConflictDoNothing();
893	    } else {
894	      const newScore = Math.max(0, (existing.score ?? 100) - 10);
895	      await db.update(userProfilesTable).set({ reliabilityScore: newScore }).where(eq(userProfilesTable.userId, userId));
896	    }
897	  }
898	
899	  res.json({ ok: true });
900	});
