1526	  }
1527	
1528	  // ─── Create Stripe checkout ──
1529	  let stripe: any;
1530	  try {
1531	    stripe = await getUncachableStripeClient();
1532	  } catch {
1533	    // No Stripe configured → mock-confirm immediately (dev mode)
1534	    const mockSessionId = `mock_session_${inserted.booking.id}_${Date.now()}`;
1535	    await db.update(bookingsTable).set({ stripeSessionId: mockSessionId, status: "confirmed" }).where(eq(bookingsTable.id, inserted.booking.id));
1536	    await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, inserted.game.id));
1537	    await db.update(courtsTable).set({ totalBookings: sql`total_bookings + 1` }).where(eq(courtsTable.id, Number(courtId)));
1538	    res.json({ checkoutUrl: `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id=${mockSessionId}`, gameId: inserted.game.id, bookingId: inserted.booking.id });
1539	    return;
1540	  }
1541	
1542	  // Resolve Connect destination: use the court owner's account.
1543	  let connectAccountId: string | null = null;
1544	  if (gameFacility?.ownerUserId) {
1545	    const [profile] = await db.select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
1546	      .from(userProfilesTable).where(eq(userProfilesTable.userId, gameFacility.ownerUserId));
1547	    if (profile?.stripeAccountId && profile.status === "active") connectAccountId = profile.stripeAccountId;
1548	  }
1549	
1550	  const amountCents = Math.round(courtPrice * 100);
1551	  const sessionParams: any = {
1552	    payment_method_types: ["card"],
1553	    line_items: [{
1554	      price_data: {
1555	        currency: "eur",
1556	        product_data: {
1557	          name: `${court.name} – žaidimas (${bookingDate} ${bookingStart}–${bookingEnd})`,
1558	          description: `Korts.lt žaidimas — kūrėjas moka už visą aikštelę.`,
1559	        },
1560	        unit_amount: amountCents,
1561	      },
1562	      quantity: 1,
1563	    }],
1564	    mode: "payment",
1565	    success_url: `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id={CHECKOUT_SESSION_ID}`,
1566	    cancel_url: cancelUrl,
1567	    // Stripe minimum is 30 minutes; our slot hold is 15 min and the cron sweeper
1568	    // will release the booking + game well before this fires.
1569	    expires_at: Math.floor(Date.now() / 1000) + 30 * 60,
1570	    metadata: { bookingId: String(inserted.booking.id), gameId: String(inserted.game.id) },
1571	    customer_email: creatorEmail,
1572	    locale: "lt",
1573	  };
1574	  if (connectAccountId) {
1575	    const applicationFeeAmount = Math.round(amountCents * 5 / 100);
1576	    sessionParams.payment_intent_data = { application_fee_amount: applicationFeeAmount, transfer_data: { destination: connectAccountId } };
1577	  }
1578	
1579	  // Compensating rollback: if Stripe session creation fails, delete the dangling
1580	  // pending game + booking so we don't hold the slot until the 15-min sweeper.
1581	  let session: Awaited<ReturnType<typeof stripe.checkout.sessions.create>>;
1582	  try {
1583	    session = await stripe.checkout.sessions.create(sessionParams);
1584	  } catch (err) {
1585	    req.log?.error?.({ err, bookingId: inserted.booking.id, gameId: inserted.game.id }, "stripe session create failed — rolling back");
1586	    await db.delete(gamesTable).where(eq(gamesTable.id, inserted.game.id));
1587	    await db.delete(bookingsTable).where(eq(bookingsTable.id, inserted.booking.id));
1588	    res.status(502).json({ error: "Nepavyko sukurti mokėjimo sesijos. Bandykite dar kartą." });
1589	    return;
1590	  }
1591	  await db.update(bookingsTable).set({ stripeSessionId: session.id }).where(eq(bookingsTable.id, inserted.booking.id));
1592	
1593	  res.json({ checkoutUrl: session.url, gameId: inserted.game.id, bookingId: inserted.booking.id });
1594	});
