1596	// ─── Exported helper: apply ELO for a confirmed result (used by /verify and the auto-confirm cron) ──
1597	export async function applyResultElo(gameResultId: number): Promise<void> {
1598	  const [result] = await db.select().from(gameResultsTable).where(eq(gameResultsTable.id, gameResultId));
1599	  if (!result) return;
1600	  if (result.status === "confirmed") return; // idempotent
1601	
1602	  // Only the FIRST caller flips status (race between /verify-confirm and cron).
1603	  const flipped = await db
1604	    .update(gameResultsTable)
1605	    .set({ status: "confirmed" })
1606	    .where(and(eq(gameResultsTable.id, gameResultId), eq(gameResultsTable.status, "pending_verification")))
1607	    .returning();
1608	  if (flipped.length === 0) return; // somebody else already promoted
1609	
1610	  await db.update(gamesTable).set({ status: "completed" }).where(eq(gamesTable.id, result.gameId));
1611	
1612	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, result.gameId));
1613	  if (!g || g.matchType !== "rated") return;
1614	
1615	  const participants = await db.select().from(gameParticipantsTable)
1616	    .where(and(eq(gameParticipantsTable.gameId, g.id), eq(gameParticipantsTable.status, "joined")));
1617	  const teamAPlayers = participants.filter(p => p.team === "A");
1618	  const teamBPlayers = participants.filter(p => p.team === "B");
1619	  const unassigned = participants.filter(p => !p.team);
1620	  const effectiveTeamA = teamAPlayers.length ? teamAPlayers : unassigned.slice(0, Math.ceil(unassigned.length / 2));
1621	  const effectiveTeamB = teamBPlayers.length ? teamBPlayers : unassigned.slice(Math.ceil(unassigned.length / 2));
1622	
1623	  const teamAWithElo = await Promise.all(effectiveTeamA.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1624	  const teamBWithElo = await Promise.all(effectiveTeamB.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1625	
1626	  const winner: "A" | "B" | "draw" =
1627	    result.scoreTeamA > result.scoreTeamB ? "A" :
1628	    result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
1629	  const changes = calculateTeamElo(teamAWithElo, teamBWithElo, winner);
1630	  const isDraw = winner === "draw";
1631	
1632	  for (const change of changes) {
1633	    const isOnTeamA = !!teamAWithElo.find(p => p.userId === change.userId);
1634	    const isWinner = isDraw ? false : (isOnTeamA ? winner === "A" : winner === "B");
1635	    const winsAdd = isDraw ? 0 : (isWinner ? 1 : 0);
1636	    const lossesAdd = isDraw ? 0 : (!isWinner ? 1 : 0);
1637	    const drawsAdd = isDraw ? 1 : 0;
1638	
1639	    await db.update(userRatingsTable)
1640	      .set({
1641	        elo: change.newElo,
1642	        wins: sql`${userRatingsTable.wins} + ${winsAdd}`,
1643	        losses: sql`${userRatingsTable.losses} + ${lossesAdd}`,
1644	        draws: sql`${userRatingsTable.draws} + ${drawsAdd}`,
1645	        updatedAt: new Date(),
1646	      })
1647	      .where(and(eq(userRatingsTable.userId, change.userId), eq(userRatingsTable.sportSlug, g.sport)));
1648	
1649	    await db.insert(eloHistoryTable).values({
1650	      userId: change.userId,
1651	      sportSlug: g.sport,
1652	      elo: change.newElo,
1653	      delta: change.delta,
1654	      gameId: g.id,
1655	    });
1656	
1657	    const sign = change.delta > 0 ? "+" : "";
1658	    await sendNotification(
1659	      change.userId,
1660	      "elo_update",
1661	      `ELO pasikeitė: ${sign}${change.delta}`,
1662	      `Žaidimas (${g.sport}) baigtas. Reitingas: ${change.oldElo} → ${change.newElo} (${sign}${change.delta}).`,
1663	      `/matches/${g.id}`,
1664	    );
1665	  }
1666	}
