1668	// ─── Sweepers (called from cron) ──
1669	export async function sweepStalePendingGames(): Promise<number> {
1670	  // Find games stuck in pending_payment for > 15 min (Stripe abandoned/expired).
1671	  const stale = await db.select({ id: gamesTable.id, bookingId: gamesTable.bookingId })
1672	    .from(gamesTable)
1673	    .where(and(
1674	      eq(gamesTable.status, "pending_payment"),
1675	      sql`${gamesTable.createdAt} < NOW() - INTERVAL '15 minutes'`,
1676	    ));
1677	  if (stale.length === 0) return 0;
1678	
1679	  for (const row of stale) {
1680	    if (row.bookingId) {
1681	      await db.update(bookingsTable)
1682	        .set({ status: "cancelled" })
1683	        .where(and(eq(bookingsTable.id, row.bookingId), ne(bookingsTable.status, "confirmed")));
1684	    }
1685	    await db.delete(gamesTable).where(and(eq(gamesTable.id, row.id), eq(gamesTable.status, "pending_payment")));
1686	  }
1687	  return stale.length;
1688	}
