1690	export async function sweepAutoConfirmResults(): Promise<number> {
1691	  const due = await db.select({ id: gameResultsTable.id })
1692	    .from(gameResultsTable)
1693	    .where(and(
1694	      eq(gameResultsTable.status, "pending_verification"),
1695	      lt(gameResultsTable.autoConfirmAt, new Date()),
1696	    ));
1697	  for (const r of due) {
1698	    try { await applyResultElo(r.id); }
1699	    catch (err) { logger.error({ err, resultId: r.id }, "auto-confirm: applyResultElo failed"); }
1700	  }
1701	  return due.length;
1702	}
